// DSB IMPLEMENTATION priv-field-finder — READ ONLY. Heuristic; review every result.
var PATTERNS = ['birth','dob','medicare','passport','licence','license','tax','tfn','address','phone','mobile','email','gender','salary','bank','account_number','health','diagnos'];
var out = {};
PATTERNS.forEach(function(p){
  var d = new GlideRecord('sys_dictionary'); d.addEncodedQuery('elementLIKE' + p + '^internal_type!=collection^nameNOT LIKEsys_^nameNOT LIKEv_'); d.setLimit(200); d.query();
  while (d.next()) { var k = d.getValue('name') + '.' + d.getValue('element'); out[k] = d.getValue('internal_type'); }
});
gs.print('=== DSB-IMPL priv-field-finder ===\n' + JSON.stringify({count: Object.keys(out).length, fields: out}, null, 2));
